describe('Modal Backdrop Close Functionality', () => {
  beforeEach(() => {
    cy.visit('/modal-page');
  });

  it('should close modal when backdrop is clicked', () => {
    // Open the modal
    cy.get('[data-testid="open-modal-button"]').click();

    // Verify modal is visible
    cy.get('[data-testid="modal-dialog"]').should('be.visible');
    cy.get('[data-testid="modal-title"]').should('contain', 'Modal Title');

    // Verify modal content is visible
    cy.get('[data-testid="modal-content"]').should('be.visible');

    // Click on the backdrop
    cy.get('[data-testid="modal-backdrop"]').click();

    // Verify modal is closed
    cy.get('[data-testid="modal-dialog"]').should('not.exist');

    // Verify modal is no longer visible
    cy.get('[data-testid="modal-dialog"]').should('not.be.visible');
  });

  it('should not close modal when backdrop is clicked while modal is disabled', () => {
    // Open the modal
    cy.get('[data-testid="open-modal-button"]').click();

    // Disable the modal
    cy.get('[data-testid="modal-dialog"]').should('be.visible');
    cy.get('[data-testid="modal-dialog"]').should('have.attr', 'disabled');

    // Verify modal is still visible and disabled
    cy.get('[data-testid="modal-dialog"]').should('be.visible');
    cy.get('[data-testid="modal-dialog"]').should('have.attr', 'disabled');

    // Click on the backdrop
    cy.get('[data-testid="modal-backdrop"]').click();

    // Verify modal is still visible and disabled
    cy.get('[data-testid="modal-dialog"]').should('be.visible');
    cy.get('[data-testid="modal-dialog"]').should('have.attr', 'disabled');

    // Verify modal content is still visible
    cy.get('[data-testid="modal-content"]').should('be.visible');
  });
});
